diff --git a/src/FADepreciationBook.Table.al b/src/FADepreciationBook.Table.al
new file mode 100644
--- /dev/null
+++ b/src/FADepreciationBook.Table.al
@@ -0,0 +1,78 @@
+table 50200 "FA Depreciation Book FP"
+{
+    DataClassification = CustomerContent;
+
+    fields
+    {
+        field(1; "FA No."; Code[20])
+        {
+            Caption = 'FA No.';
+            TableRelation = "Fixed Asset";
+        }
+
+        field(2; "Depreciation Book Code"; Code[10])
+        {
+            Caption = 'Depreciation Book Code';
+            TableRelation = "Depreciation Book";
+        }
+
+        field(3; Depreciation; Decimal)
+        {
+            FieldClass = FlowField;
+            CalcFormula = sum("FA Ledger Entry".Amount where("FA No." = field("FA No."),
+                                                            "Depreciation Book Code" = field("Depreciation Book Code"),
+                                                            "FA Posting Category" = const(Depreciation)));
+            Caption = 'Depreciation';
+        }
+
+        field(4; "Bonus Depr. Applied Amount"; Decimal)
+        {
+            FieldClass = FlowField;
+            CalcFormula = sum("FA Ledger Entry".Amount where("FA No." = field("FA No."),
+                                                            "Depreciation Book Code" = field("Depreciation Book Code"),
+                                                            "FA Posting Type" = const("Bonus Depreciation")));
+            Caption = 'Bonus Depr. Applied Amount';
+        }
+
+        field(5; "Use Half-Year Convention"; Boolean)
+        {
+            Caption = 'Use Half-Year Convention';
+
+            trigger OnValidate()
+            var
+                CannotChangeHalfYearErr: Label 'Cannot change half-year convention after depreciation has been posted.';
+                CannotChangeBonusErr: Label 'Cannot change half-year convention when bonus depreciation has been applied.';
+            begin
+                // CORRECT: CalcFields in OnValidate runs once per user edit, not in a loop
+                // This is appropriate for validation logic that needs current flowfield values
+                CalcFields(Depreciation);
+                if Depreciation <> 0 then
+                    Error(CannotChangeHalfYearErr);
+
+                CalcFields("Bonus Depr. Applied Amount");
+                if "Bonus Depr. Applied Amount" <> 0 then
+                    Error(CannotChangeBonusErr);
+            end;
+        }
+
+        field(6; "Depreciation Method"; Option)
+        {
+            OptionCaption = 'Straight-Line,Declining-Balance 1,Declining-Balance 2';
+            OptionMembers = "Straight-Line","Declining-Balance 1","Declining-Balance 2";
+            Caption = 'Depreciation Method';
+        }
+
+        field(7; "Starting Date"; Date)
+        {
+            Caption = 'Depreciation Starting Date';
+        }
+    }
+
+    keys
+    {
+        key(PK; "FA No.", "Depreciation Book Code")
+        {
+            Clustered = true;
+        }
+    }
+}
diff --git a/src/SalesOrderCard.Page.al b/src/SalesOrderCard.Page.al
new file mode 100644
--- /dev/null
+++ b/src/SalesOrderCard.Page.al
@@ -0,0 +1,87 @@
+page 50201 "Sales Order Card FP"
+{
+    PageType = Card;
+    SourceTable = "Sales Header";
+    Caption = 'Sales Order Card FP';
+
+    layout
+    {
+        area(Content)
+        {
+            group(General)
+            {
+                Caption = 'General';
+
+                field("No."; Rec."No.")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the number of the sales order.';
+                }
+
+                field("Sell-to Customer No."; Rec."Sell-to Customer No.")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the number of the customer who will receive the products on the sales order.';
+                }
+
+                field("Document Date"; Rec."Document Date")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the date when the sales order was created.';
+                }
+
+                field("Total Amount"; TotalAmount)
+                {
+                    Caption = 'Total Amount Including VAT';
+                    ApplicationArea = All;
+                    Editable = false;
+                    ToolTip = 'Specifies the total amount including VAT for the sales order.';
+                }
+            }
+        }
+    }
+
+    actions
+    {
+        area(Processing)
+        {
+            action(RefreshTotals)
+            {
+                Caption = 'Refresh totals';
+                ApplicationArea = All;
+                ToolTip = 'Recalculates and refreshes the total amount for the sales order.';
+                Image = Refresh;
+
+                trigger OnAction()
+                var
+                    TotalRefreshedMsg: Label 'Total refreshed: %1', Comment = '%1 = total amount including VAT';
+                begin
+                    // CORRECT: Manual refresh action - user-initiated, runs once
+                    Rec.CalcFields("Amount Including VAT");
+                    TotalAmount := Rec."Amount Including VAT";
+                    Message(TotalRefreshedMsg, TotalAmount);
+                end;
+            }
+        }
+    }
+
+    var
+        TotalAmount: Decimal;
+
+    // CORRECT: OnAfterGetCurrRecord fires once per record selection, not per row
+    // This is the appropriate place to calculate values when user navigates to a record
+    trigger OnAfterGetCurrRecord()
+    begin
+        // Calculate total amount when user selects a sales order
+        // This runs once when the record is loaded/selected, not in a loop
+        Rec.CalcFields("Amount Including VAT");
+        TotalAmount := Rec."Amount Including VAT";
+    end;
+
+    trigger OnNewRecord(BelowxRec: Boolean)
+    begin
+        // CORRECT: Initialize values for new record - runs once per new record creation
+        TotalAmount := 0;
+        Rec."Document Date" := WorkDate();
+    end;
+}
diff --git a/src/CustLedgerEntryAggregator.Codeunit.al b/src/CustLedgerEntryAggregator.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/CustLedgerEntryAggregator.Codeunit.al
@@ -0,0 +1,20 @@
+codeunit 50202 "Cust Ledger Entry Aggregator"
+{
+    procedure SumOpenRemainingAmount(CustomerNo: Code[20]): Decimal
+    var
+        CustLedgerEntry: Record "Cust. Ledger Entry";
+        Customer: Record Customer;
+        Total: Decimal;
+    begin
+        CustLedgerEntry.SetRange("Customer No.", CustomerNo);
+        CustLedgerEntry.SetRange(Open, true);
+        if CustLedgerEntry.FindSet() then
+            repeat
+                CustLedgerEntry.CalcFields("Remaining Amount");
+                Customer.Get(CustLedgerEntry."Customer No.");
+                if Customer."Application Method" = Customer."Application Method"::Manual then
+                    Total += CustLedgerEntry."Remaining Amount";
+            until CustLedgerEntry.Next() = 0;
+        exit(Total);
+    end;
+}

diff --git a/src/SetupReader.Codeunit.al b/src/SetupReader.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/SetupReader.Codeunit.al
@@ -0,0 +1,67 @@
+codeunit 50211 "Setup Reader"
+{
+    procedure GetSetupValues()
+    var
+        GLSetup: Record "General Ledger Setup";
+        SalesSetup: Record "Sales & Receivables Setup";
+        InventorySetup: Record "Inventory Setup";
+        PurchSetup: Record "Purchases & Payables Setup";
+    begin
+        // CORRECT: Setup tables typically have only 1 record per company
+        // Any access pattern (Get, FindSet, FindFirst) is fine for singleton tables
+        GLSetup.Get();
+        SalesSetup.Get();
+        InventorySetup.Get();
+        PurchSetup.Get();
+
+        if GLSetup."Additional Reporting Currency" <> '' then
+            ProcessACYSettings(GLSetup);
+
+        if SalesSetup."Credit Warnings" <> SalesSetup."Credit Warnings"::"No Warning" then
+            EnableCreditWarnings(SalesSetup);
+    end;
+
+    procedure ValidateCompanySettings(): Boolean
+    var
+        CompanyInfo: Record "Company Information";
+    begin
+        // CORRECT: Company Information is a singleton table (1 record per company)
+        // Get() is the appropriate method for singleton tables
+        if not CompanyInfo.Get() then
+            exit(false);
+
+        if CompanyInfo.Name = '' then
+            exit(false);
+
+        if CompanyInfo."Country/Region Code" = '' then
+            exit(false);
+
+        exit(true);
+    end;
+
+    procedure GetUserSetupForCurrentUser(var UserSetup: Record "User Setup"): Boolean
+    begin
+        // CORRECT: Looking up single user's setup record
+        // Get() with UserId is appropriate for single-record lookup
+        UserSetup.Reset();
+        if UserSetup.Get(UserId) then
+            exit(true);
+        exit(false);
+    end;
+
+    local procedure ProcessACYSettings(GLSetup: Record "General Ledger Setup")
+    var
+        ACYEnabledMsg: Label 'ACY is enabled: %1', Comment = '%1 = additional reporting currency';
+    begin
+        // Process additional currency settings
+        Message(ACYEnabledMsg, GLSetup."Additional Reporting Currency");
+    end;
+
+    local procedure EnableCreditWarnings(SalesSetup: Record "Sales & Receivables Setup")
+    var
+        CreditWarningsEnabledMsg: Label 'Credit warnings are enabled';
+    begin
+        // Enable credit warning processing
+        Message(CreditWarningsEnabledMsg);
+    end;
+}
diff --git a/src/TempBufferProcessor.Codeunit.al b/src/TempBufferProcessor.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/TempBufferProcessor.Codeunit.al
@@ -0,0 +1,61 @@
+codeunit 50210 "Temp Buffer Processor"
+{
+    procedure ProcessBufferEntries(var TempBuffer: Record "Integer" temporary)
+    var
+        ProcessedCount: Integer;
+        TotalAmount: Decimal;
+        ProcessedEntriesMsg: Label 'Processed %1 entries with total %2', Comment = '%1 = number of entries, %2 = total amount';
+    begin
+        // CORRECT: TempBuffer is temporary — all operations are in-memory, no SQL queries
+        // Any access pattern (FindSet, Get, loops) on temp tables is performant
+        ProcessedCount := 0;
+        TotalAmount := 0;
+
+        if TempBuffer.FindSet() then
+            repeat
+                // This might look suspicious, but it's CORRECT because:
+                // 1. TempBuffer is temporary (in-memory)
+                // 2. No database round trips are happening
+                // 3. All data is already loaded in memory
+                TotalAmount += TempBuffer.Number;
+                ProcessedCount += 1;
+
+                // Even modifying temp records in a loop is fine
+                TempBuffer.Number := TempBuffer.Number * 2;
+                TempBuffer.Modify();
+
+            until TempBuffer.Next() = 0;
+
+        Message(ProcessedEntriesMsg, ProcessedCount, TotalAmount);
+    end;
+
+    procedure BuildTempData(var TempBuffer: Record "Integer" temporary)
+    var
+        i: Integer;
+    begin
+        // CORRECT: Building temp data - all operations are in-memory
+        TempBuffer.Reset();
+        TempBuffer.DeleteAll();
+
+        for i := 1 to 100 do begin
+            TempBuffer.Init();
+            TempBuffer.Number := Random(1000);
+            TempBuffer.Insert();
+        end;
+    end;
+
+    procedure FindMaxValue(var TempBuffer: Record "Integer" temporary): Integer
+    var
+        MaxValue: Integer;
+    begin
+        // CORRECT: Finding max in temp table - no performance concern
+        MaxValue := 0;
+        if TempBuffer.FindSet() then
+            repeat
+                if TempBuffer.Number > MaxValue then
+                    MaxValue := TempBuffer.Number;
+            until TempBuffer.Next() = 0;
+
+        exit(MaxValue);
+    end;
+}
