diff --git a/src/BOMBufferMgt.Codeunit.al b/src/BOMBufferMgt.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/BOMBufferMgt.Codeunit.al
@@ -0,0 +1,68 @@
+codeunit 50142 "BOM Buffer Management"
+{
+    Access = Internal;
+
+    procedure CalcTotalCost(var BOMBuffer: Record "BOM Buffer")
+    var
+        Item: Record Item;
+        TotalCost: Decimal;
+        LineCount: Integer;
+    begin
+        // Initialize calculation
+        TotalCost := 0;
+        LineCount := 0;
+
+        // Validate BOM buffer has records
+        if BOMBuffer.IsEmpty() then
+            exit;
+
+        if BOMBuffer.FindSet() then
+            repeat
+                LineCount += 1;
+
+                if Item.Get(BOMBuffer."No.") then begin
+                    // Calculate cost based on costing method
+                    if ShouldUseStandardCost(Item) then
+                        TotalCost += Item."Standard Cost" * BOMBuffer."Qty. per BOM Line"
+                    else if ShouldUseAverageCost(Item) then
+                        TotalCost += Item."Unit Cost" * BOMBuffer."Qty. per BOM Line"
+                    else
+                        TotalCost += GetLastDirectCost(Item) * BOMBuffer."Qty. per BOM Line";
+                end;
+
+                // Update line with calculated cost
+                UpdateBOMLineWithCost(BOMBuffer, Item);
+
+            until BOMBuffer.Next() = 0;
+
+        // Log calculation summary
+        LogCostCalculation(LineCount, TotalCost);
+    end;
+
+    local procedure ShouldUseStandardCost(Item: Record Item): Boolean
+    begin
+        exit(Item."Costing Method" = Item."Costing Method"::Standard);
+    end;
+
+    local procedure ShouldUseAverageCost(Item: Record Item): Boolean
+    begin
+        exit(Item."Costing Method" = Item."Costing Method"::Average);
+    end;
+
+    local procedure GetLastDirectCost(Item: Record Item): Decimal
+    begin
+        exit(Item."Last Direct Cost");
+    end;
+
+    local procedure UpdateBOMLineWithCost(var BOMBuffer: Record "BOM Buffer"; Item: Record Item)
+    begin
+        BOMBuffer."Unit Cost" := Item."Unit Cost";
+        BOMBuffer."Total Cost" := BOMBuffer."Unit Cost" * BOMBuffer."Qty. per BOM Line";
+        BOMBuffer.Modify();
+    end;
+
+    local procedure LogCostCalculation(LineCount: Integer; TotalCost: Decimal)
+    begin
+        // Log calculation summary for audit
+    end;
+}
diff --git a/src/PurchRcptLineMgt.Codeunit.al b/src/PurchRcptLineMgt.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/PurchRcptLineMgt.Codeunit.al
@@ -0,0 +1,62 @@
+codeunit 50140 "Purch. Rcpt. Line Mgmt."
+{
+    Access = Internal;
+
+    procedure ProcessReceiptLines(OrderNo: Code[20])
+    var
+        PurchRcptLine: Record "Purch. Rcpt. Line";
+        ProcessedCount: Integer;
+    begin
+        // Validate order number
+        if OrderNo = '' then
+            exit;
+
+        // Setup filters for receipt lines
+        PurchRcptLine.SetRange("Order No.", OrderNo);
+        PurchRcptLine.SetRange(Type, PurchRcptLine.Type::Item);
+        PurchRcptLine.SetFilter(Quantity, '>0');
+
+        if PurchRcptLine.IsEmpty() then
+            exit;
+
+        if PurchRcptLine.FindSet() then
+            repeat
+                PurchRcptLine.CalcFields("Currency Code");
+
+                if PurchRcptLine."Currency Code" <> '' then begin
+                    ProcessForeignCurrencyLine(PurchRcptLine);
+                    ProcessedCount += 1;
+                end else
+                    ProcessLocalCurrencyLine(PurchRcptLine);
+
+                // Update line status
+                UpdateLineProcessingStatus(PurchRcptLine);
+
+            until PurchRcptLine.Next() = 0;
+
+        // Log processing completion
+        LogProcessingComplete(OrderNo, ProcessedCount);
+    end;
+
+    local procedure ProcessForeignCurrencyLine(PurchRcptLine: Record "Purch. Rcpt. Line")
+    begin
+        // Process foreign currency line with exchange rate calculations
+    end;
+
+    local procedure ProcessLocalCurrencyLine(PurchRcptLine: Record "Purch. Rcpt. Line")
+    begin
+        // Process local currency line
+    end;
+
+    local procedure UpdateLineProcessingStatus(var PurchRcptLine: Record "Purch. Rcpt. Line")
+    begin
+        // Update processing flags
+        PurchRcptLine."Processed Date" := Today();
+        PurchRcptLine.Modify();
+    end;
+
+    local procedure LogProcessingComplete(OrderNo: Code[20]; ProcessedCount: Integer)
+    begin
+        // Log completion statistics
+    end;
+}
