+page 50141 "Custom Report Layouts List"
+{
+    Caption = 'Custom Report Layouts List';
+    PageType = List;
+    SourceTable = "Custom Report Layout";
+    Editable = false;
+
+    layout
+    {
+        area(Content)
+        {
+            repeater(Lines)
+            {
+                field("Code"; Rec."Code")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the ID of the custom report layout.';
+                }
+                field(Description; Rec.Description)
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies a description of the custom report layout.';
+                }
+                field("Report ID"; Rec."Report ID")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the ID of the report.';
+                }
+                field("Report Name"; Rec."Report Name")
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the name of the report.';
+                }
+                field("Layout Format"; Rec.Type)
+                {
+                    ApplicationArea = All;
+                    ToolTip = 'Specifies the format of the layout (Word or RDLC).';
+                }
+                field(UserDisplayName; UserDisplayName)
+                {
+                    ApplicationArea = All;
+                    Caption = 'Modified By';
+                    ToolTip = 'Specifies who last modified this layout.';
+                }
+            }
+        }
+    }
+
+    trigger OnAfterGetRecord()
+    begin
+        UpdateUserDisplayName();
+    end;
+
+    local procedure UpdateUserDisplayName()
+    var
+        User: Record User;
+    begin
+        UserDisplayName := '';
+
+        // Try to get the user who last modified the record
+        if not IsNullGuid(Rec.SystemModifiedBy) then
+            if User.Get(Rec.SystemModifiedBy) then
+                UserDisplayName := User."Full Name";
+
+        // Fallback to created by user if last modified is empty
+        if UserDisplayName = '' then
+            if not IsNullGuid(Rec.SystemCreatedBy) then
+                if User.Get(Rec.SystemCreatedBy) then
+                    UserDisplayName := User."Full Name";
+
+        // Final fallback
+        if UserDisplayName = '' then
+            UserDisplayName := UnknownUserLbl;
+    end;
+
+    var
+        UserDisplayName: Text[80];
+        UnknownUserLbl: Label 'Unknown User';
+}
